 let original_a=read(format!("{P}/algebra.json"));let qs=original_a["auxiliary_primes"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()).collect::<Vec<_>>();let r=BigUint::parse_bytes(b"21888242871839275222246405745257275088548364400416034343698204186575808495617",10).unwrap();let m=qs.iter().fold(BigUint::one(),|z,&q|z*q);let c=(&r-BigUint::one()).pow(2)*32768u32;assert!(m>c*16u32);assert!(2*qs.len()*16<7*(1usize<<32));
 for &q in&qs{assert!(q>1<<30&&q<1<<31);let reciprocal=(1u128<<63)/q as u128;assert!((q as u128-1)*reciprocal<1u128<<63);let correction=(1u128<<48)/q as u128;assert!(16*q as u128*correction<1u128<<53);}
 let p4=(&r>>208usize).to_u128().unwrap();let b=1u128<<52;assert!(p4>=1u128<<45&&p4<1u128<<46);assert!(36*(p4+1)*p4+37*b<b*p4); // Potential native reducer only; not implemented.
